  populateAssemblies(){this.options($('assembly'),(this.draft?.twin.hbm_assemblies||[]).filter(a=>a.microstructure?.enabled).map(a=>({value:a.id,label:a.name||a.id})),'Choose an HBM assembly');this.defects();this.caseControls();}
  defects(){const assembly=this.draft?.twin.hbm_assemblies?.find(a=>a.id===$('assembly').value);this.options($('defect'),(assembly?.microstructure?.defects||[]).map(d=>({value:d.id,label:`${d.id} · ${d.kind} · layer ${d.layer_index}, row ${d.row}, column ${d.column}`})),'Choose a named defect');if(assembly&&!assembly.microstructure?.defects?.length)this.message('This HBM patch has no authored local defect. Author one in Edit HBM stacks, then capture the edited twin and save a recipe before creating an isolated pair.');this.invalidatePlan();}
  invalidatePlan(){this.reviewToken=(this.reviewToken||0)+1;this.reviewedProposal=null;this.idempotencyKey=null;$('submit-batch').disabled=true;if(this.plan)$('case-error').textContent='Inputs changed; the retained case table is from the previous review. Review again before submitting.';$('case-error').hidden=!this.plan;}
  async review(){try{const proposal=this.proposal(),token=this.reviewToken;$('review-cases').disabled=true;this.message('Preflighting every expanded case with the selected solver and current disk reservations…');const plan=await this.request('/api/v2/cases/preview',proposal);if(token!==this.reviewToken){this.message('Controls changed during preflight. Review the current proposal again.',true);return;}this.plan=plan;this.reviewedProposal=proposal;this.idempotencyKey=crypto.randomUUID();this.renderPlan();$('case-error').hidden=true;$('submit-batch').disabled=false;this.message('All expanded cases passed preflight. Review exact differences and resources before submitting.');}catch(error){$('case-error').hidden=false;$('case-error').textContent=`Proposal rejected; no jobs were submitted. ${error.message}`;this.reviewedProposal=null;$('submit-batch').disabled=true;this.message('Case review failed. Edit the proposal; existing inputs and the previous table are retained.',true);}finally{$('review-cases').disabled=false;}}
