  options(select,items,placeholder){const signature=JSON.stringify([items,placeholder]);if(select._optionsSignature===signature)return;select._optionsSignature=signature;const previous=select.value;select.replaceChildren();if(placeholder)select.add(new Option(placeholder,''));for(const item of items)select.add(new Option(item.label,item.value));if(items.some(item=>item.value===previous))select.value=previous;}
